```python
def reconcile(events):
    # Dicionário para armazenar os eventos mais recentes por id
    latest_events = {}

    # Itera sobre os eventos e armazena o mais recente por id
    for event in events:
        if event['id'] not in latest_events or event['seq'] > latest_events[event['id']]['seq']:
            latest_events[event['id']] = event

    # Filtra os eventos settled e calcula a soma de amount_centavos
    settled_events = [event for event in latest_events.values() if event['status'] == 'settled']
    net_centavos = sum(event['amount_centavos'] for event in settled_events)

    # Ordena os ids lexicograficamente
    ids = sorted(event['id'] for event in settled_events)

    return {'net_centavos': net_centavos, 'ids': ids}
```

```python
def expand_ranges(text):
    tokens = [token.strip() for token in text.split(',')]
    result = set()
    for token in tokens:
        if '..' in token:
            try:
                a, b = map(int, token.split('..'))
                if a > b:
                    a, b = b, a
                result.update(range(a, b + 1))
            except ValueError:
                raise ValueError(f"Token inválido: {token}")
        else:
            try:
                num = int(token)
                result.add(num)
            except ValueError:
                raise ValueError(f"Token inválido: {token}")
    return sorted(list(result))
```
